INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine UI-Anpassung immer für den Endnutzer sichtbar?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch Backend betreffen"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich visuell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem neuen Layout?', 3, '[{"text": "Benutzbarkeit verbessern", "correct": true, "because": "Erleichtert Interaktion"}, {"text": "Datenbank optimieren", "correct": false, "because": "Anderer Bereich"}, {"text": "Code kürzen", "correct": false, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer UI-Anpassung?', 5, '[{"text": "Farbschema", "correct": true, "because": "Visuelle Wahrnehmung"}, {"text": "Button-Positionen", "correct": true, "because": "Erreichbarkeit"}, {"text": "Datenbankzugriff", "correct": false, "because": "Backend-spezifisch"}, {"text": "Netzwerkprotokolle", "correct": false, "because": "Kein UI-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Layouts beeinflussen die UX. b) Sie ändern die Logik.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Logik bleibt unberührt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer UI-Anpassung?', 4, '[{"text": "Benutzerfeedback", "correct": false, "because": "Wichtig für Nutzerzufriedenheit"}, {"text": "Designrichtlinien", "correct": false, "because": "Sichern Konsistenz"}, {"text": "Serverkonfiguration", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jede Software eine anpassbare UI hat?', 2, '[{"text": "Nein", "correct": true, "because": "Manche sind festgelegt"}, {"text": "Ja", "correct": false, "because": "Nicht universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug wähle ich für Layoutänderungen?', 3, '[{"text": "CSS", "correct": true, "because": "Steuert Darstellung"}, {"text": "SQL", "correct": false, "because": "Datenbankbezogen"}, {"text": "SSH", "correct": false, "because": "Netzwerkzugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei einer UI-Anpassung entscheidend?', 5, '[{"text": "Responsivität", "correct": true, "because": "Anpassung an Geräte"}, {"text": "Konsistenz", "correct": true, "because": "Einheitliches Erlebnis"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) UI-Anpassungen sind rein kosmetisch. b) Sie verbessern Effizienz. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Effizienz durch Nutzbarkeit"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist zu eng"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine UI-Änderung?', 4, '[{"text": "Designvorgaben", "correct": false, "because": "Leiten Anpassung"}, {"text": "Testumgebung", "correct": false, "because": "Prüft Ergebnisse"}, {"text": "API-Schlüssel", "correct": true, "because": "Schnittstellenbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Müssen Layouts immer neu getestet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Sichert Funktion auf Geräten"}, {"text": "Nein", "correct": false, "because": "Risiko bei Untätigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte mache ich bei einer UI-Anpassung?', 4, '[{"text": "Feedback einholen", "correct": true, "because": "Nutzerbedürfnisse"}, {"text": "Design umsetzen", "correct": true, "because": "Visuelle Änderung"}, {"text": "Datenbank restrukturieren", "correct": false, "because": "Kein UI-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass UI-Anpassungen die Sicherheit erhöhen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Nutzererlebnis betroffen"}, {"text": "Ja", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem neuen Layout?', 3, '[{"text": "Nutzerfreundlichkeit", "correct": true, "because": "Fördert Akzeptanz"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) UI-Änderungen brauchen Tests. b) Sie sind immer optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Anforderungen ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt ein angepasstes Layout?', 5, '[{"text": "Bessere Navigation", "correct": true, "because": "Erleichtert Zugriff"}, {"text": "Höhere Zufriedenheit", "correct": true, "because": "Nutzererlebnis steigt"}, {"text": "Schnellere Datenbank", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer UI-Anpassung unwichtig?', 3, '[{"text": "Klarheit der Elemente", "correct": false, "because": "Fördert Verständnis"}, {"text": "Farbanpassung", "correct": false, "because": "Beeinflusst Wahrnehmung"}, {"text": "Serverleistung", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ändert eine UI-Anpassung die Funktionalität?', 3, '[{"text": "Nein", "correct": true, "because": "Nur Darstellung betroffen"}, {"text": "Ja", "correct": false, "because": "Logik bleibt gleich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Responsivität immer nötig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Zielgerät ab"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wähle ich, um ein Layout responsiv zu machen?', 4, '[{"text": "Media Queries", "correct": true, "because": "Passt an Bildschirmgröße"}, {"text": "Datenbankabfragen", "correct": false, "because": "Datenbezogen"}, {"text": "API-Calls", "correct": false, "because": "Schnittstellenbezogen"}]');
